const formulaData={
 'em-charge-quantization':['Q=ne；电子电荷=−e','普通宏观物体的净电荷以元电荷为份额。','n是带符号整数；e=1.602176634×10⁻¹⁹ C为正数。','普通可孤立物体的微观电荷计数；宏观测量可能舍入。','Q与e用C；n无单位。'],
 'em-charge-conservation':['ΔQ系统=Q流入−Q流出','电荷总量变化等于穿越边界的净输入。','Q流入、Q流出按代数电荷记录；必须先选系统。','一般电荷记账；孤立系统无净交换时ΔQ系统=0。','各项均用C。'],
 'em-field-definition':['E=F/q','静电场对足够小的试探电荷给出的力与电量之比。','E、F是矢量；q是带符号电荷量。','试探电荷足够小，不显著改变原源分布。','E用N/C或V/m，F用N，q用C。'],
 'em-field-point':['|E|=k|Q|/r²','点电荷场强大小；方向另由正向外、负向内判断。','Q是源电荷；r是源到场点距离；k=1/(4πε₀)。','真空静止点电荷或球对称源外部；r>0。','E用N/C，Q用C，r用m。'],
 'em-field-superposition':['E总=ΣᵢEᵢ','同一场点的各源电场按矢量相加。','Eᵢ是每个源对同一场点的贡献；Σ表示逐项求和。','静电真空线性叠加；若源分布被改变需按新分布计算。','各电场分量均用N/C。'],
 'em-field-continuous':['dq=λdl；dq=σdA；dq=ρdV','按源分布的维度选择电荷元，再累加它产生的场。','λ、σ、ρ分别是线、面、体电荷密度；dl、dA、dV为小几何元。','连续电荷近似，密度可随源位置变化。','λ用C/m，σ用C/m²，ρ用C/m³，dq用C。'],
 'em-dipole-field':['p=qℓ；E轴≈2kp/r³，E中垂≈kp/r³','小偶极的远场大小按反立方衰减。','q是正电荷量大小；ℓ为两端间距；p方向负端到正端。','真空固定偶极，r远大于ℓ；中垂面场方向反p。','p用C·m，r用m，E用N/C。'],
 'em-field-lines':['F=qE；a=F合/m','场线给局部E方向，真实运动由合力与初始条件决定。','q可正可负；F合还可含重力等；a是加速度。','非相对论质点模型；场线不是必然轨迹。','F用N，q用C，m用kg，a用m/s²。'],
 'em-electric-flux':['ΦE=EA cosθ','均匀电场穿过平面的有向通量。','A为面积；θ是E与面法向夹角，不是与平面的夹角。','E在该平面均匀；一般情况需积分。','ΦE用N·m²/C，E用N/C，A用m²。'],
 'em-gauss-law':['∮E·dA=Q内总/ε₀','闭合面总电通量由包围的全部净电荷决定。','dA按闭合面外法向；Q内总含自由与束缚电荷。','静电高斯定理；直接求场还需对称性等信息。','通量用N·m²/C，Q用C，ε₀用F/m。'],
 'em-gauss-sphere':['E内=k|Q|r/R³；E外=k|Q|/r²','均匀带电绝缘实心球的分段场强大小。','R为球半径；r为距中心距离；Q为球总电荷。','真空、均匀球对称体电荷；薄球壳内部应另用E=0。','E用N/C，Q用C，r、R用m。'],
 'em-gauss-line-plane':['E线=|λ|/(2πε₀r)；E单平面=|σ|/(2ε₀)','不同高对称源产生不同距离依赖的场。','λ为线密度；σ为单一非导体无限薄面密度。','真空无限长线或无限均匀平面近似；导体表面与双板勿混用。','λ用C/m，σ用C/m²，E用N/C。'],
 'em-millikan':['|q|E=mg（忽略浮力等时）','悬浮油滴由电力平衡重力，反推电荷量。','m是滴质量；g是重力加速度；方向应让电力向上。','简化静止受力平衡；精确实验需浮力、阻力与半径测量修正。','q用C，E用N/C，m用kg，g用m/s²。'],
 'em-field-work':['WAB=q(VA−VB)','静电力做功等于电势能减少。','q是带符号电量；VA、VB是同参考下两点电势。','固定静电源或相应外场模型；不直接套感应环路。','W用J，q用C，V用V。'],
 'em-electrostatic-loop':['∮E·dl=0','静电场沿闭合路径的环流为零。','dl沿选定回路方向；∮表示绕完整闭合路径积分。','静电场；随时间变化的磁通可使电场环流非零。','环流用V，E用V/m，dl用m。'],
 'em-electric-potential-energy':['ΔU=−W电；U=qV','势能变化与静电功反号；试探电荷势能由外势给定。','U是电荷与源配置的相互作用势能；q带符号。','静电保守外场；固定源背景下不把自身势重复计入。','U、W用J，q用C，V用V。'],
 'em-potential-definition':['V=U/q；VB−VA=−∫A→B E·dl','电势是单位电荷的能量高度，势差来自场积分。','U是该电荷在外场中的电势能；q非零且含符号。','静电场并统一参考零点；q不显著改变源。','V用V=J/C；E用V/m，dl用m。'],
 'em-potential-superposition':['V=ΣᵢkQᵢ/rᵢ','统一零点后，点源电势保留电荷正负作标量相加。','Qᵢ是各源代数电量；rᵢ是各源到场点距离。','有限静止点源，真空，无穷远统一零势，场点不在源上。','V用V，Q用C，r用m。'],
 'em-potential-continuous':['V=∫k dq/r','连续源的电势由每份电荷的标量势累加。','r是电荷元到固定场点的距离，不一定可提出积分号。','有限分布且无穷远零点适用；无限源可改用有限参考势差。','V用V，dq用C，r用m。'],
 'em-equipotential':['VA=VB ⇒ WAB=0','同一等势面始末点间的静电功为零。','VA、VB需同一参考；WAB针对任意给定q的静电功。','静电等势面；零功不表示E或电力必为零。','V用V，W用J。'],
 'em-potential-gradient':['E=−∇V；Eₓ=−dV/dx（一维）','场是电势下降最快的方向及其变化率。','∇V为各方向电势变化率组成的梯度；一维式只给x分量。','静电势可微区域；边界两侧必要时分别求极限。','E用V/m，V用V，x用m。'],
 'em-dipole-torque':['τ=p×E；|τ|=pE sinθ','均匀外场可给偶极力偶转矩而合力为零。','p从负端指向正端；θ是p与外E夹角。','固定刚性偶极处于均匀外场；小偶极近似可推广局部场。','τ用N·m，p用C·m，E用N/C。'],
 'em-dipole-energy':['U=−p·E=−pE cosθ','固定偶极矩与均匀外场的取向势能。','取θ=90°为零能；θ为p与E夹角。','固定永久或刚性偶极；诱导可变p不直接照搬。','U用J，p用C·m，E用N/C。'],
 'em-conductor-equilibrium':['E材料内=0；V连通导体=常数','静电平衡时自由电荷重排，导体材料内无总场。','V常数由参考和外界决定，不必为零。','静电平衡导体材料内部；稳定电流导体不属此零场模型。','E用N/C，V用V。'],
 'em-conductor-distribution':['Q内表=−q腔；Q外表=Q导体+q腔','由材料内高斯面和导体电荷守恒分配总量。','q腔是封闭腔内源总电荷；Q导体是导体自身净电荷。','孤立静电平衡封闭导体，内源不接触壁；接地时另列交换。','各电荷均用C。'],
 'em-electrostatic-shielding':['E材料=0；E无源封闭腔=0','材料零场与无源空腔零场来自不同条件。','无源指腔内无电荷；封闭与等势边界缺一不可。','理想导体静电平衡、完整无源空腔；动态场需另行分析。','E用N/C，腔内常数电势用V。'],
 'em-dielectric-linear':['ε=εrε₀；C=εA/d','完全填介质的平板容量随电容率变化。','εr为相对电容率；ε为绝对电容率；A面积、d间距。','线性各向同性均匀介质完全填充；忽略平板边缘。','ε用F/m，εr无单位，C用F。'],
 'em-polarization':['P=Δp/ΔV；P=ε₀χeE','P是局部平均偶极矩的体积密度。','Δp为体积ΔV中的总偶极矩；χe为电极化率。','第一式为宏观局部平均；第二式需线性各向同性材料。','P用C/m²，p用C·m，ΔV用m³。'],
 'em-bound-charge':['σb=P·n̂；ρb=−∇·P','面束缚荷看极化外法向投影，体束缚荷看空间变化。','n̂为介质外法向；∇·P表示极化的净穿出密度。','宏观极化连续介质模型，边界两侧需各自取外法向。','σb用C/m²，ρb用C/m³，P用C/m²。'],
 'em-displacement-field':['D=ε₀E+P；线性各向同性时D=εE','把极化整理进D，并附上简化材料关系。','E是真实电场；P是极化强度；ε为材料电容率。','宏观定义一般成立；标量ε式需线性各向同性。','D、P用C/m²，E用V/m，ε用F/m。'],
 'em-dielectric-gauss':['∮D·dA=Q内自由','电位移的闭合面通量只数内部自由净电荷。','dA沿外法向；束缚响应已包含在D定义中。','宏观介质模型；求点值还需边界、对称性与材料关系。','D用C/m²，通量与Q自由用C。'],
 'em-isolated-capacitance':['C=Q/V；球C=4πε₀R','孤立球电容由半径决定，电荷与电势同比变化。','V相对无穷远；R为球外半径，Q为球净电荷。','真空孤立导体球，无邻近导体影响，线性静电模型。','C用F，Q用C，V用V，R用m。'],
 'em-capacitor-geometry':['C平板=εA/d；C球壳=4πεab/(b−a)','电容由介质和导体几何共同确定。','A是单板面积；d为间距；a<b是同心球半径。','均匀线性介质；平板忽略边缘；球壳同心完整。','C用F，ε用F/m，长度用m、面积用m²。'],
 'em-capacitor-series-parallel':['C并=ΣCᵢ；1/C串=Σ1/Cᵢ','并联同压，标准串联的隔离中间节点使单板电量同大小。','Cᵢ为每只电容；简单串联各中间节点初始净荷零。','理想线性元件、标准串并联网络；带初始节点荷须额外列账。','各容量均用F，倒数用1/F。'],
 'em-capacitive-touch':['ΔQ=ΔC·ΔU（固定电压摆幅）','读出电路可把等效容量变化换成可测电荷变化。','ΔC是触摸前后容量差；ΔU为固定测量电压摆幅。','简化线性读出；实际自电容和互电容的变化符号需看结构。','ΔQ用C，ΔC用F，ΔU用V。'],
 'em-capacitor-energy':['W=Q²/(2C)=CU²/2=QU/2','建立线性电容电场的可逆储能。','Q为单板电量大小；U为板间电压；C固定线性容量。','线性被动电容；过程中的电源功和电阻热需另算。','W用J，Q用C，C用F，U用V。'],
 'em-electric-energy-density':['u真空=ε₀E²/2；u线性介质=E·D/2','用局部能量密度对场区体积积分得到储能。','u是每单位体积能量；W=∫u dV。','介质式需线性可逆无损准静态模型；非线性或色散需另分析。','u用J/m³，W用J，E用V/m，D用C/m²。'],
 'em-capacitor-constraints':['恒Q：W=Q²/(2C)；恒U：W=CU²/2','固定量不同，增大C时的储能趋势相反。','恒Q对应断电且漏电忽略；恒U对应理想恒压源连接。','均匀线性无损介质、准静态过程；机械功还需含电源账。','W用J，Q用C，C用F，U用V。'],
 'em-rc-charging':['uC=U₀(1−e^(−t/RC))；τ=RC','未充电电容的电压逐渐接近恒压源。','U₀为源电压；R为串联总电阻；C为电容；t从切换后计。','理想恒压阶跃、有限R、初压零的集中参数RC模型。','uC、U₀用V，R用Ω，C用F，τ、t用s。'],
 'em-rc-discharging':['uC=U初e^(−t/RC)；W=W初e^(−2t/RC)','电压指数衰减，储能因平方关系衰减更快。','U初、W初为放电起始状态；R是闭合放电路径总电阻。','理想RC放电、无源闭合路径，忽略漏电以外的复杂材料效应。','电压用V，储能用J，R用Ω，C用F，t用s。'],
 'em-van-de-graaff':['V≈Q/(4πε₀R)；E表≈V/R','近似球壳的电势与表面场联系电荷累积和放电限制。','R为光滑球壳半径；Q为净电荷；V相对远处环境。','真空或空气近似孤立球；邻近结构与尖端会改变实际场。','V用V，Q用C，R用m，E用V/m。'],
 'em-electrostatic-precipitation':['v迁移≈|q|E/(6πηa)','电力与线性黏性阻力平衡后的横向终端速度。','η是气体动力黏度；a是球形颗粒半径；q为给定电荷。','低雷诺数球形Stokes模型，忽略滑移修正和荷电变化。','v用m/s，q用C，E用N/C，η用Pa·s，a用m。'],
 'em-electrostatic-separation':['y=qE(L/v)²/(2m)','固定荷质比差异可在相同通过时间内造成不同偏移。','L为场区长度；v为初始纵向速度；y是有向横向位移。','横向初速零、匀强场、q固定，忽略其他横向力和碰撞。','y、L用m，v用m/s，q用C，E用N/C，m用kg。']
};
